/* - v1.1
Source: brunocalado
Icon: icons/environment/people/commoner.webp
*/

(async () => {
  const faction1 = await drawFromTable('Factions');
  const faction2 = await drawFromTable('Factions');
  const client = await drawFromTable('Client / Target');
  const target = await drawFromTable('Client / Target');
  const twist = await drawFromTable('Twist');
  const place = await drawFromTable('Job Location');
  const task = await drawFromTable('Work');
  const connection = await drawFromTable('Connection');

  let msg1 = `<h2>Job</h2>`;
  let msg2 = `<ul><li>Faction 1: <b>${faction1}</b></li>`;
  msg2 += `<li>Faction 2: <b>${faction2}</b></li>`;
  msg2 += `<li>Client: <b>${client}</b></li>`;
  msg2 += `<li>Target: <b>${target}</b></li>`;
  msg2 += `<li>Twist: <b>${twist}</b></li>`;
  msg2 += `<li>Job Location: <b>${place}</b></li>`;
  msg2 += `<li>Job: <b>${task}</b></li>`;
  msg2 += `<li>Connection: <b>${connection}</b></li></ul>`;

  let message=msg1 + msg2;
  let msgId = foundry.utils.randomID();

  let data = {
    name: `${task}`,
    content: message
  };          

  message+=`<button style="background:#d10000;color:white" id="createJob-`
  message+=msgId;
  message+=`">Save As Journal Entry</button>`;

  let chatData = {
    content: message,
    whisper : ChatMessage.getWhisperRecipients("GM")
  };  
  ChatMessage.create(chatData, {});  

  addEventListenerOnHtmlElement("#createJob-" + msgId, 'click', (e) => {
    createJob(data, "Job", msg2);    
  });
})()

/* Functions */
async function drawFromTable(tableName) {

  let roll_compendiums;
  let job_compendiums;
  roll_compendiums = game.packs.filter( p => p.documentName === 'RollTable');
  job_compendiums = await roll_compendiums.filter( p => p.metadata.label === 'Job Tables' )[0].getDocuments();
  const table = await job_compendiums.filter( p=> p.name === tableName )[0];        

  if (!table) {
    ui.notifications.warn(`Table ${tableName} not found.`, {});
    return;
  }
  const output = await table.roll();
  const result = output.results[0].text;
  return result;  
}

function addEventListenerOnHtmlElement(element, event, func){    
  Hooks.on("renderChatMessage", (chatItem, html, data) => {
    if( html[0].querySelector(element) !== null ) {
      html[0].querySelector(element).addEventListener(event, func);
    }
  });
}

async function createJob(data, msg1, msg2) {

  let folder;
  if( game.folders.find( f => f.name === "Job Ideas") === undefined ) {
    folder = await Folder.create( {
      name: "Job Ideas",
      type: "JournalEntry"
    } );
  } else {
    folder = game.folders.find( f => f.name === "Job Ideas");
  }
  data.folder = folder;

  const instantAdventure = await JournalEntry.create({"name": msg1, "folder": data.folder});

  data.type = "text";
  data.text = {}
  data.text.content = msg2;

  await instantAdventure.createEmbeddedDocuments("JournalEntryPage", [data]);
  await instantAdventure.sheet.render(true);    
}

Change XP Bars.command:
const version = '1.1';

/*
https://raw.githubusercontent.com/brunocalado/mestre-digital/master/Foundry%20VTT/Macros/Forged%20in%20the%20Dark/BladesintheDark-XpBar.js
icon: icons/sundries/misc/lock-open-yellow.webp
*/

let tokenD;

if (canvas.tokens.controlled[0] === undefined){
  ui.notifications.warn("You must select a token!");    
} else {
  tokenD = canvas.tokens.controlled[0].actor;
  main();
}

async function main() {
  let attribute = [];
  if(tokenD.type === 'character'){
    attribute = Object.keys( game.model.Actor.character.attributes );
    attribute.push("class");
    attribute.push("stress");
  } else if(tokenD.type === 'ship'){
    attribute = ["crew"];
  }

  let attributeList = ``;
  attribute.map((t) => {
    attributeList += `<option value="${t}">${t}</option>`;
  });

  new Dialog({
    title: `XP/Stress Bar - Manager - v${version}`,
    content: `
    <h2>Bar Size</h2>
    <p>      
      <input type="number" min=1 max=12 id="xpBarSize" value="6"/>
    </p><br>
    <h2>Choose Bar</h2>
    <p>    
      <select id="attribute" type="text" style="width: 100px;">
        ${attributeList}
      </select>  
    </p>    
    `,
    buttons: {
      roll: {
        label: "Change",
        callback: (html) => {
          changeActorSheetBar(html);
        }
      }, 
      cancel: {
        label: "Cancel"
      }
    }
  }).render(true)
}

async function changeActorSheetBar(html) {
  const xpBarSize = parseInt( html.find("#xpBarSize")[0].value );  
  let attribute = html.find("#attribute")[0].value;
  let updated;  

  switch( attribute ){
    case 'class':
      updated = await Actor.updateDocuments([{_id: tokenD.id, "system.experienceMax": xpBarSize}]);
      break;
    case 'crew':
      updated = await Actor.updateDocuments([{_id: tokenD.id, "system.crew_experienceMax": xpBarSize}]);
      break;
    case 'stress':
      updated = await Actor.updateDocuments([{_id: tokenD.id, "system.stress.max": xpBarSize, "system.stress.max_default": xpBarSize}]);
      break;
    default:
      let key = "system.attributes." + attribute + ".expMax"; 
      updated = await Actor.updateDocuments([{_id: tokenD.id, [key]: xpBarSize}]);
    }
}
